type TutorialExecutionContract = { tenantId: string; idempotencyKey: string; runId: string; attempt: number; version: string };

export function validateTutorialExecution(input: TutorialExecutionContract) {
  if (!input.tenantId || !input.idempotencyKey || !input.runId || input.attempt < 1) {
    throw new Error('invalid execution contract');
  }
  return input;
}

